//! Closed original BQ049: three original modes (positive task-region input is not yet available); generated TK010 retains its own ruling.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="BQ049";
pub(crate) const KEY:&str="bq049-spread";
const TITLE:&str="吞噬蔓延：牺牲一个本方角色，获得4名誉";
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn region_slot()->TargetSlotSpec{target(Zone::Region,EntityKind::Any,Relation::Any,Range::Anywhere)}
pub(crate) fn definition()->Definition{let mut a=ability(KEY,"吞噬蔓延：选择一项",Timing::Fast,vec![],vec![],vec![],None);a.play_only=true;a.modes=vec![Mode{key:"sacrifice".into(),label:TITLE.into(),targets:vec![],ops:vec![Op::BQ049Sacrifice]},Mode{key:"mobility".into(),label:"本方核心和触手获得本回合机动，获得1名誉".into(),targets:vec![],ops:vec![Op::BQ049Grant]},Mode{key:"generate".into(),label:"目标地区生成触手；本方任务地区放置1势力".into(),targets:vec![region_slot()],ops:vec![Op::BQ049Generate]}];with_abilities(vec![a])}
fn selected()->Vec<AbilitySpec>{let a=definition().abilities.remove(0);let mut all=vec![a.clone()];for m in &a.modes{let mut s=a.clone();s.targets=m.targets.clone();s.ops=m.ops.clone();s.modes.clear();all.push(s);}all}
fn op_related(o:&Op)->bool{matches!(o,Op::BQ049Sacrifice|Op::BQ049Grant|Op::BQ049Generate)}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("bq049-")||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(op_related)}
fn frame_related(f:&ResolutionFrame)->bool{f.source.card.definition==ID||f.ability_key.starts_with("bq049-")||f.steps.iter().any(|s|op_related(&s.op))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!selected().iter().any(|s|same(s,a)){return Err("吞噬蔓延须保留原三个快速模式".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("吞噬蔓延完整定义不可删改或移植".into());}Ok(())}
pub(crate) fn validate_action(c:&Card,a:&Action)->RuleResult<()>{if c.definition!=ID{return Ok(());}if *a==(Action{card_id:a.card_id.clone(),..Action::new("asset")}){return Ok(());}let generate=a.option.as_deref()==Some("generate");if !matches!(a.option.as_deref(),Some("sacrifice"|"mobility"|"generate"))||a.ability_id.as_deref().is_some_and(|k|k!=KEY)||*a!=(Action{card_id:a.card_id.clone(),ability_id:a.ability_id.clone(),option:a.option.clone(),region:if generate{a.region}else{None},..Action::new("play")}){return Err("吞噬蔓延只接受原模式及其地区目标".into());}Ok(())}
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Grant{pub frame:Box<ResolutionFrame>,pub recipient:Card,pub turn:u32}
pub(crate) fn mobility_ability(p:Grant)->AbilitySpec{let mut a=crate::mobility::ability();a.ops=vec![Op::BQ049Move{proof:Box::new(p)}];a}
pub(crate) fn mobility_proof(a:&AbilitySpec)->Option<&Grant>{if let [Op::BQ049Move{proof}]=a.ops.as_slice(){Some(proof)}else{None}}
pub(crate) fn canonical_mobility(a:&AbilitySpec)->bool{mobility_proof(a).is_some_and(|p|same(a,&mobility_ability(p.clone())))}
impl Game{
 pub(crate) fn validate_bq049_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !frame_related(f){return Ok(());}self.validate_resource_frame(f)?;let s=&f.source;let c=&s.card;let Some(a)=selected().into_iter().find(|a|a.modes.is_empty()&&same(&a.ops,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>()))else{return Err("吞噬蔓延原模式程序损坏".into());};
 if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||c.face_down||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||f.ability_key!=KEY||f.cursor>1||f.chosen_region!=f.targets.first().and_then(|t|t.id.strip_prefix("region:").and_then(|r|r.parse().ok()))||f.steps.iter().any(|s|s.context!=f.actor)||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||f.targets.len()!=a.targets.len()||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if f.money_units(0)<=2&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len()&&ids.iter().all(|id|id!=&c.id&&self.mystic_instance_number(id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b))){return Err("吞噬蔓延来源、支付或执行阶段损坏".into());}
 for(t,spec)in f.targets.iter().zip(a.targets){if !same(&t.spec,&spec)||t.region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some(){return Err("吞噬蔓延原地区目标损坏".into());}}self.mobility_immutable_identity(c)
 }
 fn bq049_options(&self,actor:usize)->Vec<ChoiceOption>{self.regions.iter().enumerate().filter(|(_,r)|!r.vacant).flat_map(|(r,x)|x.cards.iter().map(move|c|(r,c))).filter(|(_,c)|!c.face_down&&c.controller==actor&&catalog::has_kind(catalog::card(&c.definition),"character")).map(|(r,c)|self.option(c,actor,Some(r),None)).collect()}
 pub(crate) fn bq049_sacrifice(&mut self,f:ResolutionFrame)->RuleResult<()>{self.validate_bq049_frame(&f)?;if f.cursor!=1||!matches!(f.steps[0].op,Op::BQ049Sacrifice){return Err("吞噬蔓延牺牲阶段无效".into());}if self.players[f.actor].eliminated{return Ok(());}let options=self.bq049_options(f.actor);if !options.is_empty(){self.choice(f.actor,"target",TITLE.into(),options,1,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::BQ049Sacrifice});}Ok(())}
 pub(crate) fn bq049_finish(&mut self,f:&ResolutionFrame,seat:usize,a:&Action,ids:&[String])->RuleResult<()>{self.validate_bq049_frame(f)?;if f.cursor!=1||!matches!(f.steps[0].op,Op::BQ049Sacrifice)||seat!=f.actor||ids.len()!=1||*a!=(Action{choice_id:a.choice_id.clone(),selected:Some(ids.to_vec()),..Action::new("choose")})||!self.bq049_options(seat).iter().any(|o|o.id==ids[0]){return Err("吞噬蔓延须牺牲当前本人操控的一个明置角色".into());}self.remove_dead(&ids[0],RemovalCause::Sacrifice);self.players[seat].honor=self.players[seat].honor.checked_add(4).ok_or("名誉溢出")?;Ok(())}
 fn bq049_recipient(&self,c:&Card,actor:usize)->bool{!c.face_down&&c.controller==actor&&self.board(&c.id).is_some()&&(crate::tentacle::character(c)||c.owner==actor&&self.selected_core_card(c))}
 pub(crate) fn bq049_grant(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_bq049_frame(f)?;if f.cursor!=1||!matches!(f.steps[0].op,Op::BQ049Grant){return Err("吞噬蔓延机动阶段无效".into());}if self.players[f.actor].eliminated{return Ok(());}let cards=self.regions.iter().flat_map(|r|&r.cards).filter(|c|self.bq049_recipient(c,f.actor)).cloned().collect::<Vec<_>>();for c in cards{self.bq049_grants.push(Grant{frame:Box::new(f.clone()),recipient:c,turn:self.turn});}self.players[f.actor].honor=self.players[f.actor].honor.checked_add(1).ok_or("名誉溢出")?;Ok(())}
 pub(crate) fn bq049_generate(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_bq049_frame(f)?;if f.cursor!=1||!matches!(f.steps[0].op,Op::BQ049Generate){return Err("吞噬蔓延生成阶段无效".into());}let t=&f.targets[0];if self.players[f.actor].eliminated||!self.valid_bound_target(f.actor,&f.source,t){return Ok(());}let r=t.id.strip_prefix("region:").and_then(|s|s.parse::<usize>().ok()).ok_or("目标地区无效")?;let c=self.make_generated(crate::generated::GeneratedKind::Tentacle,f.actor)?;let id=c.id.clone();self.regions[r].cards.push(c);self.enter_triggers(f.actor,crate::tentacle::ID,&id,false);if self.regions[r].card.owner==f.actor&&catalog::card(&self.regions[r].card.definition).kind=="region"&&catalog::card(&self.regions[r].card.definition).subtypes.iter().any(|s|s=="任务"){self.place_influence(f.actor,r,1);}Ok(())}
 fn validate_bq049_grant(&self,g:&Grant)->RuleResult<()>{self.validate_bq049_frame(&g.frame)?;let c=&g.recipient;if g.turn!=self.turn||g.frame.cursor!=1||!matches!(g.frame.steps[0].op,Op::BQ049Grant)||c.face_down||c.controller!=g.frame.actor||c.owner>=self.players.len()||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&g.frame.frame_id)).is_some_and(|(a,b)|a<b)||!(crate::tentacle::character(c)||c.owner==g.frame.actor&&self.core_zones.iter().any(|z|z.owner==c.owner&&z.definition==c.definition)){return Err("吞噬蔓延机动授予来源、回合或原接收者损坏".into());}self.mobility_immutable_identity(c)}
 pub(crate) fn bq049_mobility(&self,c:&Card)->Option<Grant>{if c.face_down||self.board(&c.id).is_none(){return None;}self.bq049_grants.iter().find(|g|g.turn==self.turn&&g.recipient.id==c.id).cloned()}
 pub(crate) fn bq049_event_ability(&self,actor:usize,s:&SourceSnapshot)->Option<AbilitySpec>{if self.validate_mobility_source(actor,s).is_ok()||self.xg12_event_ability(actor,s).is_some(){return None;}self.bq049_mobility(&s.card).map(mobility_ability)}
 pub(crate) fn validate_bq049_mobility_source(&self,actor:usize,s:&SourceSnapshot,g:&Grant)->RuleResult<()>{self.validate_mobility_recipient(actor,s)?;self.validate_bq049_grant(g)?;if s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||s.card.id!=g.recipient.id||s.card.definition!=g.recipient.definition||s.card.owner!=g.recipient.owner||s.card.generated!=g.recipient.generated{return Err("吞噬蔓延机动不能移植接收者".into());}Ok(())}
 pub(crate) fn validate_bq049_play(&self,i:&StackItem)->RuleResult<()>{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(frame_related){let f=i.frame.as_ref().ok_or("吞噬蔓延实际事务缺帧")?;self.validate_bq049_frame(f)?;if f.source.card.definition!=ID||f.cursor!=0||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.as_deref()!=f.targets.first().map(|t|t.id.as_str())||i.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("吞噬蔓延实际事务外壳损坏".into());}}Ok(())}
 pub(crate) fn validate_bq049_state(&self)->RuleResult<()>{let mut grants=BTreeSet::new();for g in &self.bq049_grants{self.validate_bq049_grant(g)?;if !grants.insert((&g.frame.frame_id,&g.recipient.id)){return Err("吞噬蔓延同次授予重复接收者".into());}}
 let mut seen=BTreeSet::new();let mut check=|f:&ResolutionFrame|->RuleResult<()>{self.validate_bq049_frame(f)?;if frame_related(f)&&!seen.insert(f.frame_id.clone()){return Err("吞噬蔓延同帧重复续体".into());}Ok(())};
 for i in &self.stack{self.validate_bq049_play(i)?;if let Some(f)=&i.frame{check(f)?;}}for e in &self.effects{match e{Effect::Frame{frame}=>check(frame)?,Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)=>return Err("吞噬蔓延不是触发声明".into()),_=>{}}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Frame{frame:f,choice}if frame_related(f)||matches!(choice,FrameChoice::BQ049Sacrifice)=>{check(f)?;if f.source.card.definition!=ID||f.cursor!=1||!matches!(f.steps[0].op,Op::BQ049Sacrifice)||!matches!(choice,FrameChoice::BQ049Sacrifice)||self.players[f.actor].eliminated||p.seat!=f.actor||p.choice.player_id!=player_id(f.actor)||p.choice.kind!="target"||p.choice.title!=TITLE||p.choice.min!=Some(1)||p.choice.max!=Some(1)||p.choice.allow_decline!=Some(false)||p.choice.amount.is_some()||!p.choice.preview_cards.is_empty()||self.bq049_options(f.actor).is_empty()||!same(&p.choice.options,&self.bq049_options(f.actor)){return Err("吞噬蔓延牺牲待选损坏".into());}},ChoiceResolution::Declare{declaration:d,..}if d.source.card.definition==ID||related(&d.ability)=>return Err("吞噬蔓延无触发待选".into()),_=>{}}}Ok(())}
}
